// UI-ordbøker for bibel. Engelsk er KILDESPRÅKET (I18N.md §1): `en` definerer
// nøkkelsettet og de sju andre typer seg mot den, så en manglende eller
// feilstavet nøkkel blir en kompileringsfeil framfor en stille fallback.
//
// Her ligger KUN grensesnittet. Bibelteksten og det deriverte innholdet
// (sammendrag, kontekst, temaer) er egne pipelines med sin egen språkakse i
// lib/lang.ts, og oversettes ikke herfra (Vegard 2026-07-25).

