  "about.title": "About",
  "about.meta": "About the Bible project: open source, Bible translations, KVN versification and study aids.",
  "about.h1": "About this site",
  "about.project": "The project",
  "about.projectBody": "This Bible site is part of an open project to make the Bible available with good study tools. Both the website and all the Bible data are open source and freely available.",
  "about.repoSite": "the source code for this website",
  "about.repoData": "Bible data (text, original languages, references and more)",
  "about.translations": "Bible translations",
  "about.osnb": "Norwegian text (OSNB)",
  "about.osnbBody": "The Norwegian text is an open translation that is freely available for anyone to use.",
  "about.tanach": "Hebrew original text (Tanach)",
  "about.tanachBody": "The Hebrew text of the Old Testament is based on the open Tanach text from Tanach.us.",
  "about.sblgnt": "Greek original text (SBLGNT)",
  "about.sblgntBody": "The Greek text of the New Testament is the SBL Greek New Testament, published by the Society of Biblical Literature and Logos Bible Software.",
  "about.sblgntGitHub": "SBLGNT on GitHub",
  "about.kvn": "Versification (KVN)",
  "about.kvnBody1": "Bible translations number their verses differently. A verse called Genesis 31:55 in the Norwegian Bible Society’s translation (2024) is called Genesis 32:1 in our source text (osnb), because the Hebrew tradition divides the chapters differently from the European one.",
  "about.kvnExample": "For example in Genesis around chapters 31–32:",
  "about.kvnColA": "Bible Society 2024",
  "about.kvnColB": "osnb (Hebrew)",
  "about.kvnColText": "Text",
  "about.kvnBody2": "Such differences occur in more than a thousand verses, especially in the Psalms (where the headings are sometimes counted as a verse of their own), and in several chapters of the Pentateuch, Joel and other prophets where the chapter boundaries are shifted.",
  "about.kvnBody3a": "To handle this we use",
  "about.kvnBody3b": "(Canonical Verse Number) – a system that gives every verse in the Bible a unique number independent of translation. When you choose a versification under “Settings” or in the study aids panel, KVN is used to show the correct verse numbers for the chosen tradition, even though the underlying text is the same.",
  "about.kvnSupports": "KVN currently supports",
  "about.kvnSystems": "12 different numbering systems",
  "about.kvnIncluding": ", including the Norwegian Bible Society’s translations (1930, 1978, 2011, 2024), Norsk Bibel (1988, 1994), the King James Version and more.",
  "about.studyTools": "Study tools",
