  "about.sc.quickNav": "Quick navigation (H=Home, S=Search, L=Reading plan, T=Timeline, P=Prophecies, F=Favourites, E=Topics, N=Notes, K=Well-known verses, O=People, V=Verse lists, A=Parallels, I=Statistics, M=Manuscripts, C=Themes, D=Days, Y=Numbers)",
  "about.verseInteraction": "Verse interaction",
  "about.verseClickBody": "Click the verse number to open the verse details with the following tabs:",
  "about.lbl.versions": "Versions",
  "about.vi.originalText": "Hebrew/Greek original text (click a word for its translation)",
  "about.vi.refs": "Cross-references to other Bible verses",
  "about.vi.prophecies": "Prophecies linked to the verse (where relevant)",
  "about.vi.topics": "Tag the verse with your own topics",
  "about.vi.notes": "Write your own notes on the verse",
  "about.vi.versions": "Compare with other Bible translations",
  "about.under": "Under",
  "about.verseListsBody": "you can collect Bible verses in named lists for manuscripts, Bible classes or study. Enter references such as «Joh 3,16» or «Sal 23,1-6» to add verses. You can reorder them and copy a link that shows all the verses.",
  "about.manuscriptsBody1": "you can write devotionals, sermons, Bible classes and other texts. Use",
  "about.manuscriptsBody2": "to insert verse references. The side panel gives you access to:",
  "about.lbl.context": "Context",
  "about.ms.bible": "Look up and insert verses directly into the text",
  "about.ms.manuscripts": "Search your other manuscripts",
  "about.ms.context": "Automatic summaries and historical context for the chapters you reference",
  "about.ms.timeline": "Timeline events linked to the chapters you reference",
  "about.aidsPanel": "The study aids panel",
  "about.aidsPanelBody": "On mobile, tap the gear (⚙) to open the study aids. On desktop they are shown in a side panel.",
  "about.offline": "Offline access",
  "about.offlineBody": "This site also works without an internet connection. Chapters you have read are saved automatically on your device, so you can read them again even when you are offline.",
  "about.autoSave": "Automatic saving",
  "about.autoSaveBody": "When you read a chapter it is saved automatically in the browser cache. The next time you visit the same chapter without a connection, the saved version is shown.",
  "about.downloadAll": "Download the whole Bible",
  "about.downloadAllBody": "You can also download the whole Bible in advance (part of FLOGVIT.plus). Go to the",
  "about.offlinePage": "offline page",
  "about.downloadAllBody2": "to:",
  "about.dl1": "Download OSEN (English), OSNB (Norwegian bokmål) and/or OSNN (Norwegian nynorsk) — the original text (Hebrew/Greek with word-by-word), cross-references and summaries come with every chapter",
  "about.dl2": "Download the timeline, prophecies, people and reading plans for offline use",
  "about.dl3": "See which chapters are saved and how much storage is used",
  "about.dl4": "Delete saved data",
  "about.updates": "Updates",
  "about.updatesBody": "When the app itself is updated, you get a notice with the option to load the new version straight away. The offline page shows which content version you have downloaded; if new Bible content arrives, you update by deleting the saved data and downloading again.",
  "about.contact": "Contact",
  "about.email": "Email:",
  "about.reportGitHub": "Bugs and suggestions can also be reported on GitHub:",
  "a11y.meta": "Accessibility statement for the Bible site: WCAG 2.2 AA, keyboard navigation, screen reader support.",
  "a11y.h1": "Accessibility statement",
  "a11y.about": "About accessibility on this site",
  "a11y.aboutBody": "bible.flogvit.com is built to be accessible to everyone, regardless of ability. The site is built with server-rendered HTML: all content is readable without JavaScript, and navigation is ordinary page loads.",
  "a11y.status": "Status",
  "a11y.conformance": "Conformance status:",
  "a11y.partial": "Partially conformant with WCAG 2.1 AA",
  "a11y.tested": "Last tested July 2026: automated testing with axe-core (WCAG 2.0/2.1 level A and AA) on every page type found no violations, and a machine review of more than 250 pages confirmed the structure (headings, landmarks, alt texts, links). Manual testing with screen readers remains — hence “partially conformant”.",
  "a11y.limits": "Known limitations",
  "a11y.limitsIntro": "We are aware of the following areas that may have accessibility problems:",
  "a11y.lim1": "Not all features have been tested with screen readers (VoiceOver/NVDA)",
  "a11y.lim2": "Colour contrast in dark mode has not been reviewed separately",
  "a11y.lim3": "Offline functionality and uploading your own translations are still under development",
  "a11y.limitsOutro": "We are actively working to test and fix any problems.",
  "a11y.whatWeDo": "What are we doing?",
  "a11y.structure": "Structure and semantics",
  "a11y.s1": "Semantic, structured HTML with correct landmark regions",
  "a11y.s2": "Skip link to jump straight to the main content",
  "a11y.s3": "Correct heading hierarchy (h1-h6)",
  "a11y.s4": "Breadcrumbs on every page for orientation",
  "a11y.s5": "Language marking on Hebrew and Greek text (lang attribute)",
  "a11y.s6": "Abbreviations explained with the abbr tag",
  "a11y.s7": "ARIA labels on all interactive elements",
  "a11y.s8": "aria-live regions for status messages",
  "a11y.visual": "Visual accessibility",
  "a11y.v1": "Colour contrast that meets the WCAG AA requirement (4.5:1)",
  "a11y.v2": "Information is never conveyed by colour alone (icons/symbols as well)",
  "a11y.v3": "Clear focus indicator on every clickable element",
  "a11y.v4": "Adjustable text size (small/medium/large)",
  "a11y.v5": "Dark mode for reduced light exposure",
