  "about.sc.quickNav": "Hurtignavigasjon (H=Hjem, S=Søk, L=Leseplan, T=Tidslinje, P=Profetier, F=Favoritter, E=Emner, N=Notater, K=Kjente vers, O=Personer, V=Verslister, A=Paralleller, I=Statistikk, M=Manuskripter, C=Temaer, D=Dager, Y=Tall)",
  "about.verseInteraction": "Versinteraksjon",
  "about.verseClickBody": "Klikk på versnummeret for å åpne versdetaljer med følgende faner:",
  "about.lbl.versions": "Versjoner",
  "about.vi.originalText": "Hebraisk/gresk originaltekst (klikk på ord for oversettelse)",
  "about.vi.refs": "Kryssreferanser til andre bibelvers",
  "about.vi.prophecies": "Profetier knyttet til verset (hvis relevant)",
  "about.vi.topics": "Tag verset med egne emner",
  "about.vi.notes": "Skriv egne notater til verset",
  "about.vi.versions": "Sammenlign med andre bibeloversettelser",
  "about.under": "Under",
  "about.verseListsBody": "kan du samle bibelvers i navngitte lister for manuskripter, bibeltimer eller studier. Skriv inn referanser som «Joh 3,16» eller «Sal 23,1-6» for å legge til vers. Du kan endre rekkefølge og kopiere en lenke som viser alle versene.",
  "about.manuscriptsBody1": "kan du skrive andakter, prekener, bibeltimer og andre tekster. Bruk",
  "about.manuscriptsBody2": "for å sette inn versreferanser. Sidepanelet gir deg tilgang til:",
  "about.lbl.context": "Kontekst",
  "about.ms.bible": "Slå opp og sett inn vers direkte i teksten",
  "about.ms.manuscripts": "Søk i andre manuskripter",
  "about.ms.context": "Automatisk sammendrag og historisk kontekst for refererte kapitler",
  "about.ms.timeline": "Tidslinjehendelser knyttet til refererte kapitler",
  "about.aidsPanel": "Hjelpemidler-panelet",
  "about.aidsPanelBody": "På mobil, trykk på tannhjulet (⚙) for å åpne hjelpemidler. På desktop vises disse i et sidepanel.",
  "about.offline": "Offline-tilgang",
  "about.offlineBody": "Denne siden fungerer også uten internett. Kapitler du har lest blir automatisk lagret på enheten din, slik at du kan lese dem igjen selv om du er offline.",
  "about.autoSave": "Automatisk lagring",
  "about.autoSaveBody": "Når du leser et kapittel, lagres det automatisk i nettleserens cache. Neste gang du besøker det samme kapittelet uten nett, vises den lagrede versjonen.",
  "about.downloadAll": "Last ned hele Bibelen",
  "about.downloadAllBody": "Du kan også laste ned hele Bibelen på forhånd (en del av FLOGVIT.plus). Gå til",
  "about.offlinePage": "offline-siden",
  "about.downloadAllBody2": "for å:",
  "about.dl1": "Laste ned OSEN (engelsk), OSNB (bokmål) og/eller OSNN (nynorsk) — grunnteksten (hebraisk/gresk med ord-for-ord), kryssreferanser og sammendrag følger med hvert kapittel",
  "about.dl2": "Laste ned tidslinje, profetier, personer og leseplaner for offline-bruk",
  "about.dl3": "Se hvilke kapitler som er lagret og hvor mye lagringsplass som brukes",
  "about.dl4": "Slette lagrede data",
  "about.updates": "Oppdateringer",
  "about.updatesBody": "Når selve appen oppdateres, får du et varsel med mulighet til å laste den nye versjonen med en gang. Offline-siden viser hvilken innholdsversjon du har lastet ned; kommer det nytt bibelinnhold, oppdaterer du ved å slette lagrede data og laste ned på nytt.",
  "about.contact": "Kontakt",
  "about.email": "E-post:",
  "about.reportGitHub": "Feil og forslag kan også meldes inn på GitHub:",
  "a11y.meta": "Tilgjengelighetserklæring for bibelsiden: WCAG 2.2 AA, tastaturnavigasjon, skjermleserstøtte.",
  "a11y.h1": "Tilgjengelighetserklæring",
  "a11y.about": "Om tilgjengelighet på denne siden",
  "a11y.aboutBody": "bible.flogvit.com er utviklet for å være tilgjengelig for alle, uavhengig av funksjonsevne. Siden er bygget med server-rendret HTML: alt innhold er lesbart uten JavaScript, og navigasjon er vanlige sidelastinger.",
  "a11y.status": "Status",
  "a11y.conformance": "Samsvarsstatus:",
  "a11y.partial": "Delvis i samsvar med WCAG 2.1 AA",
  "a11y.tested": "Sist testet juli 2026: automatisk testing med axe-core (WCAG 2.0/2.1 nivå A og AA) på alle sidetyper ga ingen brudd, og en maskinell gjennomgang av over 250 sider bekreftet struktur (overskrifter, landemerker, alt-tekster, lenker). Manuell testing med skjermlesere gjenstår — derfor «delvis i samsvar».",
  "a11y.limits": "Kjente begrensninger",
  "a11y.limitsIntro": "Vi er klar over følgende områder som kan ha tilgjengelighetsproblemer:",
  "a11y.lim1": "Ikke alle funksjoner er testet med skjermlesere (VoiceOver/NVDA)",
  "a11y.lim2": "Fargekontrast i mørk modus er ikke revidert separat",
  "a11y.lim3": "Offline-funksjonalitet og opplasting av egne oversettelser er under utvikling",
  "a11y.limitsOutro": "Vi jobber aktivt med å teste og utbedre eventuelle problemer.",
  "a11y.whatWeDo": "Hva gjør vi?",
