  "about.title": "Om",
  "about.meta": "Om bibelprosjektet: open kjeldekode, bibelomsetjingar, KVN-versnummerering og hjelpemiddel.",
  "about.h1": "Om denne sida",
  "about.project": "Prosjektet",
  "about.projectBody": "Denne bibelsida er ein del av eit ope prosjekt for å gjere Bibelen tilgjengeleg med gode studieverktøy. Både nettsida og alle bibeldata er open kjeldekode og fritt tilgjengeleg.",
  "about.repoSite": "kjeldekoden til denne nettsida",
  "about.repoData": "bibeldata (tekst, grunntekst, referansar, m.m.)",
  "about.translations": "Bibelomsetjingar",
  "about.osnb": "Norsk tekst (OSNB)",
  "about.osnbBody": "Den norske teksten er ei open omsetjing som er fritt tilgjengeleg for alle å bruke.",
  "about.tanach": "Hebraisk grunntekst (Tanach)",
  "about.tanachBody": "Den hebraiske teksten for Det gamle testamentet byggjer på den opne Tanach-teksten frå Tanach.us.",
  "about.sblgnt": "Gresk grunntekst (SBLGNT)",
  "about.sblgntBody": "Den greske teksten for Det nye testamentet er SBL Greek New Testament, utgjeven av Society of Biblical Literature og Logos Bible Software.",
  "about.sblgntGitHub": "SBLGNT på GitHub",
  "about.kvn": "Versnummerering (KVN)",
  "about.kvnBody1": "Ulike bibelomsetjingar nummererer vers ulikt. Eit vers som heiter 1. Mosebok 31,55 i omsetjinga til Bibelselskapet (2024) heiter 1. Mosebok 32,1 i grunnteksten vår (osnb), fordi den hebraiske tradisjonen deler kapitla annleis enn den europeiske.",
  "about.kvnExample": "Til dømes i 1. Mosebok kring kapittel 31–32:",
  "about.kvnColA": "Bibelselskapet 2024",
  "about.kvnColB": "osnb (hebraisk)",
  "about.kvnColText": "Tekst",
  "about.kvnBody2": "Slike skilnader finst i over tusen vers, særleg i Salmane (der overskrifter av og til blir talde som eige vers), og i fleire kapittel i Mosebøkene, Joel og andre profetar der kapittelgrensene er forskjøvne.",
  "about.kvnBody3a": "For å handtere dette bruker vi",
  "about.kvnBody3b": "(Kanonisk Versnummer) – eit system som gjev kvart vers i Bibelen eit unikt nummer uavhengig av omsetjing. Når du vel ei versnummerering under «Innstillingar» eller i hjelpemiddelpanelet, blir KVN brukt til å vise rette versnummer for den valde tradisjonen, sjølv om den underliggjande teksten er den same.",
  "about.kvnSupports": "KVN støttar i dag",
  "about.kvnSystems": "12 ulike nummereringssystem",
  "about.kvnIncluding": ", inkludert omsetjingane til Bibelselskapet (1930, 1978, 2011, 2024), Norsk Bibel (1988, 1994), King James Version og fleire.",
  "about.studyTools": "Studieverktøy",
