  "about.helpIntro": "Her er nokre tips for å få mest mogleg ut av sida:",
  "about.navigation": "Navigasjon",
  "about.nav1": "Bruk søkefeltet øvst for å søkje etter vers eller tekst",
  "about.nav2a": "Skriv ein referanse som",
