  "about.sc.focusSearch": "Fokuser søkefeltet",
  "about.sc.readingMode": "Lesemodus på/av",
  "about.sc.prevNextChapter": "Førre/neste kapittel",
  "about.sc.jumpVerse": "Hopp til vers 1-9",
  "about.sc.letter": "bokstav",
  "about.sc.quickNav": "Snøggnavigasjon (H=Heim, S=Søk, L=Leseplan, T=Tidslinje, P=Profetiar, F=Favorittar, E=Emne, N=Notat, K=Kjende vers, O=Personar, V=Verslister, A=Parallellar, I=Statistikk, M=Manuskript, C=Tema, D=Dagar, Y=Tal)",
  "about.verseInteraction": "Versinteraksjon",
  "about.verseClickBody": "Klikk på versnummeret for å opne versdetaljar med desse fanene:",
  "about.lbl.versions": "Versjonar",
  "about.vi.originalText": "Hebraisk/gresk originaltekst (klikk på ord for omsetjing)",
  "about.vi.refs": "Kryssreferansar til andre bibelvers",
  "about.vi.prophecies": "Profetiar knytte til verset (om relevant)",
  "about.vi.topics": "Merk verset med eigne emne",
  "about.vi.notes": "Skriv eigne notat til verset",
  "about.vi.versions": "Samanlikn med andre bibelomsetjingar",
  "about.under": "Under",
  "about.verseListsBody": "kan du samle bibelvers i namngjevne lister for manuskript, bibeltimar eller studium. Skriv inn referansar som «Joh 3,16» eller «Sal 23,1-6» for å leggje til vers. Du kan endre rekkjefølgja og kopiere ei lenkje som viser alle versa.",
  "about.manuscriptsBody1": "kan du skrive andakter, preiker, bibeltimar og andre tekstar. Bruk",
  "about.manuscriptsBody2": "for å setje inn versreferansar. Sidepanelet gjev deg tilgang til:",
  "about.lbl.context": "Kontekst",
  "about.ms.bible": "Slå opp og set inn vers direkte i teksten",
  "about.ms.manuscripts": "Søk i andre manuskript",
  "about.ms.context": "Automatisk samandrag og historisk kontekst for refererte kapittel",
  "about.ms.timeline": "Tidslinjehendingar knytte til refererte kapittel",
  "about.aidsPanel": "Hjelpemiddel-panelet",
  "about.aidsPanelBody": "På mobil, trykk på tannhjulet (⚙) for å opne hjelpemidla. På desktop blir dei viste i eit sidepanel.",
  "about.offline": "Offline-tilgang",
  "about.offlineBody": "Denne sida fungerer òg utan internett. Kapittel du har lese blir automatisk lagra på eininga di, slik at du kan lese dei att sjølv om du er offline.",
  "about.autoSave": "Automatisk lagring",
  "about.autoSaveBody": "Når du les eit kapittel, blir det automatisk lagra i mellomlageret til nettlesaren. Neste gong du vitjar det same kapittelet utan nett, blir den lagra versjonen vist.",
  "about.downloadAll": "Last ned heile Bibelen",
  "about.downloadAllBody": "Du kan òg laste ned heile Bibelen på førehand (ein del av FLOGVIT.plus). Gå til",
  "about.offlinePage": "offline-sida",
  "about.downloadAllBody2": "for å:",
  "about.dl1": "Laste ned OSEN (engelsk), OSNB (bokmål) og/eller OSNN (nynorsk) — grunnteksten (hebraisk/gresk med ord-for-ord), kryssreferansar og samandrag følgjer med kvart kapittel",
  "about.dl2": "Laste ned tidslinje, profetiar, personar og leseplanar for offline-bruk",
  "about.dl3": "Sjå kva kapittel som er lagra og kor mykje lagringsplass som blir brukt",
  "about.dl4": "Slette lagra data",
  "about.updates": "Oppdateringar",
  "about.updatesBody": "Når sjølve appen blir oppdatert, får du eit varsel med høve til å laste den nye versjonen med ein gong. Offline-sida viser kva innhaldsversjon du har lasta ned; kjem det nytt bibelinnhald, oppdaterer du ved å slette lagra data og laste ned på nytt.",
  "about.contact": "Kontakt",
  "about.email": "E-post:",
  "about.reportGitHub": "Feil og framlegg kan òg meldast inn på GitHub:",
  "a11y.meta": "Tilgjengeerklæring for bibelsida: WCAG 2.2 AA, tastaturnavigasjon, skjermlesarstøtte.",
  "a11y.h1": "Tilgjengeerklæring",
  "a11y.about": "Om tilgjenge på denne sida",
  "a11y.aboutBody": "bible.flogvit.com er utvikla for å vere tilgjengeleg for alle, uavhengig av funksjonsevne. Sida er bygd med server-rendra HTML: alt innhald er lesbart utan JavaScript, og navigasjon er vanlege sidelastingar.",
  "a11y.status": "Status",
  "a11y.conformance": "Samsvarsstatus:",
  "a11y.partial": "Delvis i samsvar med WCAG 2.1 AA",
  "a11y.tested": "Sist testa juli 2026: automatisk testing med axe-core (WCAG 2.0/2.1 nivå A og AA) på alle sidetypar gav ingen brot, og ein maskinell gjennomgang av over 250 sider stadfesta strukturen (overskrifter, landemerke, alt-tekstar, lenkjer). Manuell testing med skjermlesarar står att — difor «delvis i samsvar».",
  "a11y.limits": "Kjende avgrensingar",
  "a11y.limitsIntro": "Vi er klar over desse områda som kan ha tilgjengeproblem:",
  "a11y.lim1": "Ikkje alle funksjonar er testa med skjermlesarar (VoiceOver/NVDA)",
  "a11y.lim2": "Fargekontrast i mørk modus er ikkje revidert separat",
  "a11y.lim3": "Offline-funksjonalitet og opplasting av eigne omsetjingar er under utvikling",
  "a11y.limitsOutro": "Vi arbeider aktivt med å teste og utbetre eventuelle problem.",
  "a11y.whatWeDo": "Kva gjer vi?",
