  "about.sc.focusSearch": "Fokusera sökfältet",
  "about.sc.readingMode": "Läsläge på/av",
  "about.sc.prevNextChapter": "Föregående/nästa kapitel",
  "about.sc.jumpVerse": "Hoppa till vers 1-9",
  "about.sc.letter": "bokstav",
  "about.sc.quickNav": "Snabbnavigering (H=Startsida, S=Sök, L=Läsplan, T=Tidslinje, P=Profetior, F=Favoriter, E=Ämnen, N=Anteckningar, K=Kända verser, O=Personer, V=Verslistor, A=Paralleller, I=Statistik, M=Manuskript, C=Teman, D=Dagar, Y=Tal)",
  "about.verseInteraction": "Versinteraktion",
  "about.verseClickBody": "Klicka på versnumret för att öppna versdetaljerna med följande flikar:",
  "about.lbl.versions": "Versioner",
  "about.vi.originalText": "Hebreisk/grekisk originaltext (klicka på ett ord för översättning)",
  "about.vi.refs": "Korsreferenser till andra bibelverser",
  "about.vi.prophecies": "Profetior kopplade till versen (om relevant)",
  "about.vi.topics": "Tagga versen med egna ämnen",
  "about.vi.notes": "Skriv egna anteckningar till versen",
  "about.vi.versions": "Jämför med andra bibelöversättningar",
  "about.under": "Under",
  "about.verseListsBody": "kan du samla bibelverser i namngivna listor för manuskript, bibelstudier eller studier. Skriv in referenser som ”Joh 3,16” eller ”Sal 23,1-6” för att lägga till verser. Du kan ändra ordningen och kopiera en länk som visar alla verserna.",
  "about.manuscriptsBody1": "kan du skriva andakter, predikningar, bibelstudier och andra texter. Använd",
  "about.manuscriptsBody2": "för att infoga versreferenser. Sidopanelen ger dig tillgång till:",
  "about.lbl.context": "Kontext",
  "about.ms.bible": "Slå upp och infoga verser direkt i texten",
  "about.ms.manuscripts": "Sök i dina andra manuskript",
  "about.ms.context": "Automatiska sammanfattningar och historisk kontext för de kapitel du hänvisar till",
  "about.ms.timeline": "Tidslinjehändelser kopplade till de kapitel du hänvisar till",
  "about.aidsPanel": "Hjälpmedelspanelen",
  "about.aidsPanelBody": "På mobilen trycker du på kugghjulet (⚙) för att öppna hjälpmedlen. På datorn visas de i en sidopanel.",
  "about.offline": "Offlineåtkomst",
  "about.offlineBody": "Den här webbplatsen fungerar även utan internet. Kapitel du har läst sparas automatiskt på din enhet, så att du kan läsa dem igen även när du är offline.",
  "about.autoSave": "Automatisk sparning",
  "about.autoSaveBody": "När du läser ett kapitel sparas det automatiskt i webbläsarens cache. Nästa gång du besöker samma kapitel utan uppkoppling visas den sparade versionen.",
  "about.downloadAll": "Ladda ner hela Bibeln",
  "about.downloadAllBody": "Du kan också ladda ner hela Bibeln i förväg (en del av FLOGVIT.plus). Gå till",
  "about.offlinePage": "offlinesidan",
  "about.downloadAllBody2": "för att:",
  "about.dl1": "Ladda ner OSEN (engelska), OSNB (bokmål) och/eller OSNN (nynorska) — grundtexten (hebreiska/grekiska med ord för ord), korsreferenser och sammanfattningar följer med varje kapitel",
  "about.dl2": "Ladda ner tidslinje, profetior, personer och läsplaner för offline-bruk",
  "about.dl3": "Se vilka kapitel som är sparade och hur mycket lagringsutrymme som används",
  "about.dl4": "Radera sparade data",
  "about.updates": "Uppdateringar",
  "about.updatesBody": "När själva appen uppdateras får du en avisering med möjlighet att ladda den nya versionen direkt. Offlinesidan visar vilken innehållsversion du har laddat ner; kommer det nytt bibelinnehåll uppdaterar du genom att radera sparade data och ladda ner på nytt.",
  "about.contact": "Kontakt",
  "about.email": "E-post:",
  "about.reportGitHub": "Fel och förslag kan även rapporteras på GitHub:",
  "a11y.meta": "Tillgänglighetsredogörelse för bibelsidan: WCAG 2.2 AA, tangentbordsnavigering, skärmläsarstöd.",
  "a11y.h1": "Tillgänglighetsredogörelse",
  "a11y.about": "Om tillgängligheten på den här webbplatsen",
  "a11y.aboutBody": "bible.flogvit.com är utvecklad för att vara tillgänglig för alla, oavsett funktionsförmåga. Webbplatsen är byggd med serverrenderad HTML: allt innehåll är läsbart utan JavaScript och navigeringen sker med vanliga sidladdningar.",
  "a11y.status": "Status",
  "a11y.conformance": "Överensstämmelse:",
  "a11y.partial": "Delvis förenlig med WCAG 2.1 AA",
  "a11y.tested": "Senast testad i juli 2026: automatisk testning med axe-core (WCAG 2.0/2.1 nivå A och AA) på alla sidtyper gav inga brister, och en maskinell genomgång av över 250 sidor bekräftade strukturen (rubriker, landmärken, alt-texter, länkar). Manuell testning med skärmläsare återstår — därför ”delvis förenlig”.",
  "a11y.limits": "Kända begränsningar",
  "a11y.limitsIntro": "Vi känner till följande områden som kan ha tillgänglighetsproblem:",
  "a11y.lim1": "Alla funktioner har inte testats med skärmläsare (VoiceOver/NVDA)",
  "a11y.lim2": "Färgkontrasten i mörkt läge har inte granskats separat",
  "a11y.lim3": "Offlinefunktionalitet och uppladdning av egna översättningar är under utveckling",
  "a11y.limitsOutro": "Vi arbetar aktivt med att testa och åtgärda eventuella problem.",
  "a11y.whatWeDo": "Vad gör vi?",
