  "about.under": "En",
  "about.verseListsBody": "puedes reunir versículos en listas con nombre para manuscritos, clases bíblicas o estudios. Escribe referencias como «Joh 3,16» o «Sal 23,1-6» para añadir versículos. Puedes cambiar el orden y copiar un enlace que muestre todos los versículos.",
  "about.manuscriptsBody1": "puedes escribir devocionales, sermones, clases bíblicas y otros textos. Usa",
  "about.manuscriptsBody2": "para insertar referencias de versículos. El panel lateral te da acceso a:",
  "about.lbl.context": "Contexto",
