  "about.ms.timeline": "Acontecimientos de la cronología vinculados a los capítulos citados",
  "about.aidsPanel": "El panel de herramientas",
  "about.aidsPanelBody": "En el móvil, pulsa la rueda dentada (⚙) para abrir las herramientas. En el escritorio se muestran en un panel lateral.",
  "about.offline": "Acceso sin conexión",
  "about.offlineBody": "Este sitio también funciona sin internet. Los capítulos que has leído se guardan automáticamente en tu dispositivo, de modo que puedes volver a leerlos aunque estés sin conexión.",
  "about.autoSave": "Guardado automático",
  "about.autoSaveBody": "Cuando lees un capítulo, se guarda automáticamente en la caché del navegador. La próxima vez que visites ese mismo capítulo sin conexión, se mostrará la versión guardada.",
  "about.downloadAll": "Descargar toda la Biblia",
  "about.downloadAllBody": "También puedes descargar toda la Biblia por adelantado (forma parte de FLOGVIT.plus). Ve a la",
  "about.offlinePage": "página sin conexión",
  "about.downloadAllBody2": "para:",
  "about.dl1": "Descargar OSEN (inglés), OSNB (bokmål) u OSNN (nynorsk) — el texto original (hebreo/griego con palabra por palabra), las referencias cruzadas y los resúmenes acompañan a cada capítulo",
  "about.dl2": "Descargar la cronología, las profecías, los personajes y los planes de lectura para usarlos sin conexión",
  "about.dl3": "Ver qué capítulos están guardados y cuánto espacio de almacenamiento se usa",
  "about.dl4": "Borrar los datos guardados",
  "about.updates": "Actualizaciones",
  "about.updatesBody": "Cuando se actualiza la propia aplicación, recibes un aviso con la opción de cargar la nueva versión de inmediato. La página sin conexión muestra qué versión del contenido has descargado; si llega contenido bíblico nuevo, actualízalo borrando los datos guardados y descargándolos otra vez.",
  "about.contact": "Contacto",
  "about.email": "Correo electrónico:",
  "about.reportGitHub": "Los errores y las sugerencias también se pueden comunicar en GitHub:",
  "a11y.meta": "Declaración de accesibilidad del sitio bíblico: WCAG 2.2 AA, navegación por teclado, compatibilidad con lectores de pantalla.",
  "a11y.h1": "Declaración de accesibilidad",
  "a11y.about": "Sobre la accesibilidad de este sitio",
  "a11y.aboutBody": "bible.flogvit.com está desarrollado para ser accesible para todo el mundo, con independencia de su capacidad. El sitio está construido con HTML renderizado en el servidor: todo el contenido se puede leer sin JavaScript y la navegación son cargas de página normales.",
  "a11y.status": "Estado",
  "a11y.conformance": "Estado de conformidad:",
  "a11y.partial": "Parcialmente conforme con WCAG 2.1 AA",
  "a11y.tested": "Última prueba en julio de 2026: las pruebas automáticas con axe-core (WCAG 2.0/2.1 niveles A y AA) en todos los tipos de página no detectaron incumplimientos, y una revisión automatizada de más de 250 páginas confirmó la estructura (encabezados, regiones, textos alternativos, enlaces). Queda pendiente la prueba manual con lectores de pantalla; de ahí «parcialmente conforme».",
  "a11y.limits": "Limitaciones conocidas",
  "a11y.limitsIntro": "Somos conscientes de las siguientes áreas que pueden presentar problemas de accesibilidad:",
  "a11y.lim1": "No todas las funciones se han probado con lectores de pantalla (VoiceOver/NVDA)",
  "a11y.lim2": "El contraste de color en modo oscuro no se ha revisado por separado",
  "a11y.lim3": "La funcionalidad sin conexión y la subida de traducciones propias están en desarrollo",
  "a11y.limitsOutro": "Trabajamos activamente para probar y corregir cualquier problema.",
  "a11y.whatWeDo": "¿Qué hacemos?",
