  "about.title": "Über",
  "about.meta": "Über das Bibelprojekt: Open Source, Bibelübersetzungen, KVN-Verszählung und Hilfsmittel.",
  "about.h1": "Über diese Seite",
  "about.project": "Das Projekt",
  "about.projectBody": "Diese Bibelseite ist Teil eines offenen Projekts, das die Bibel mit guten Studienwerkzeugen zugänglich machen will. Sowohl die Website als auch sämtliche Bibeldaten sind Open Source und frei verfügbar.",
  "about.repoSite": "der Quellcode dieser Website",
  "about.repoData": "Bibeldaten (Text, Urtext, Verweise usw.)",
  "about.translations": "Bibelübersetzungen",
  "about.osnb": "Norwegischer Text (OSNB)",
  "about.osnbBody": "Der norwegische Text ist eine offene Übersetzung, die alle frei verwenden dürfen.",
  "about.tanach": "Hebräischer Urtext (Tanach)",
  "about.tanachBody": "Der hebräische Text des Alten Testaments beruht auf dem offenen Tanach-Text von Tanach.us.",
  "about.sblgnt": "Griechischer Urtext (SBLGNT)",
  "about.sblgntBody": "Der griechische Text des Neuen Testaments ist das SBL Greek New Testament, herausgegeben von der Society of Biblical Literature und Logos Bible Software.",
  "about.sblgntGitHub": "SBLGNT auf GitHub",
  "about.kvn": "Verszählung (KVN)",
  "about.kvnBody1": "Bibelübersetzungen zählen die Verse unterschiedlich. Ein Vers, der in der Übersetzung der Norwegischen Bibelgesellschaft (2024) 1. Mose 31,55 heißt, heißt in unserem Grundtext (osnb) 1. Mose 32,1, weil die hebräische Tradition die Kapitel anders einteilt als die europäische.",
  "about.kvnExample": "Zum Beispiel in 1. Mose rund um die Kapitel 31–32:",
  "about.kvnColA": "Bibelgesellschaft 2024",
  "about.kvnColB": "osnb (hebräisch)",
  "about.kvnColText": "Text",
  "about.kvnBody2": "Solche Unterschiede gibt es in über tausend Versen, besonders in den Psalmen (wo die Überschriften manchmal als eigener Vers gezählt werden) und in mehreren Kapiteln der Bücher Mose, bei Joel und anderen Propheten, wo die Kapitelgrenzen verschoben sind.",
  "about.kvnBody3a": "Um damit umzugehen, verwenden wir",
  "about.kvnBody3b": "(Kanonische Versnummer) – ein System, das jedem Vers der Bibel eine eindeutige Nummer unabhängig von der Übersetzung gibt. Wenn du unter „Einstellungen“ oder im Hilfsmittelbereich eine Verszählung wählst, zeigt KVN die richtigen Versnummern für die gewählte Tradition an, obwohl der zugrunde liegende Text derselbe ist.",
  "about.kvnSupports": "KVN unterstützt derzeit",
  "about.kvnSystems": "12 verschiedene Zählsysteme",
  "about.kvnIncluding": ", darunter die Übersetzungen der Norwegischen Bibelgesellschaft (1930, 1978, 2011, 2024), Norsk Bibel (1988, 1994), die King James Version und weitere.",
  "about.studyTools": "Studienwerkzeuge",
  "common.references": "Verweise",
