  "about.personalTools": "Persönliche Werkzeuge",
  "about.rememberBody": "Das Merken — das Speichern persönlicher Daten wie Favoriten, Notizen und eigener Übersetzungen sowie der Offline-Download — ist Teil von",
  "about.pt.favorites": "Speichere deine Lieblingsverse",
  "about.pt.topics": "Versieh Verse mit eigenen Themen",
  "about.pt.notes": "Schreibe eigene Notizen zu Versen",
