  "a11y.feedback": "Rückmeldung",
  "a11y.feedbackBody": "Hast du Probleme mit der Barrierefreiheit dieser Seite? Wir freuen uns über Rückmeldungen, damit wir besser werden können.",
  "a11y.reportGitHub": "Du kannst Probleme auch auf GitHub melden:",
  "a11y.authority": "Aufsichtsbehörde",
  "a11y.authorityBody": "Die norwegische Digitalisierungsbehörde (Digdir) ist die Aufsichtsbehörde für die universelle Gestaltung von IKT in Norwegen. Wenn du meinst, dass wir deine Anfrage nicht zufriedenstellend beantwortet haben, kannst du dich an Digdir wenden.",
